    FRQ(70, 9, "9.3", r"For which $a$ is $\begin{pmatrix}a&2\\2&a\end{pmatrix}$ positive definite?", r"$a > 2$",
        [r"Sylvester: $a > 0$ and $\det = a^2 - 4 > 0$.", r"Together: $a > 2$."]),
    FRQ(72, 9, "9.5", r"[Proof] Prove that $A^TA \succeq 0$, and that $A^TA \succ 0$ if and only if the columns of $A$ are independent.", "Model proof below.",
        [r"$\mathbf x^TA^TA\mathbf x = \|A\mathbf x\|^2 \ge 0$, with equality iff $A\mathbf x = 0$.",
         r"It is never 0 for $\mathbf x \ne 0$ exactly when $N(A) = \{\mathbf 0\}$, i.e. the columns are independent."]),
    FRQ(73, 10, "10.1", r"Find the singular values of $A = \begin{pmatrix}3&0\\4&5\end{pmatrix}$.", r"$3\sqrt5$ and $\sqrt5$",
        [r"$A^TA = \begin{pmatrix}25&20\\20&25\end{pmatrix}$, eigenvalues 45 and 5.", r"$\sigma = \sqrt{45}, \sqrt5$. Check: $\sigma_1\sigma_2 = 15 = |\det A|$."]),
    FRQ(74, 10, "10.1", r"Write an SVD $U\Sigma V^T$ of $\begin{pmatrix}2&0\\0&-3\end{pmatrix}$ (with $\sigma_1 \ge \sigma_2$).",
        r"$U = \begin{pmatrix}0&1\\-1&0\end{pmatrix}$, $\Sigma = \operatorname{diag}(3, 2)$, $V = \begin{pmatrix}0&1\\1&0\end{pmatrix}$",
        [r"$\mathbf v_1 = \mathbf e_2$, $\mathbf u_1 = A\mathbf e_2/3 = (0, -1)$; $\mathbf v_2 = \mathbf e_1$, $\mathbf u_2 = (1, 0)$.", r"Multiply back to check."]),
    FRQ(78, 10, "10.4", r"$A$ has singular values 5, 3, 1. Find the error of the best rank-1 approximation in the spectral norm and in the Frobenius norm.",
        r"$3$ and $\sqrt{10}$",
        [r"Eckart&ndash;Young: spectral error $\sigma_2 = 3$.", r"Frobenius error $\sqrt{\sigma_2^2 + \sigma_3^2} = \sqrt{9 + 1}$."]),
    FRQ(80, 10, "10.5", r"Find the pseudoinverse of $A = \begin{pmatrix}1\\2\end{pmatrix}$.", r"$A^+ = \begin{pmatrix}\tfrac15 & \tfrac25\end{pmatrix}$",
        [r"Independent columns: $A^+ = (A^TA)^{-1}A^T = \tfrac15(1\ \ 2)$."]),
    FRQ(82, 11, "11.1", r"Compute $\nabla_{\mathbf x}\|A\mathbf x - \mathbf b\|^2$. Set it to zero; what equation do you get?",
        r"$2A^T(A\mathbf x - \mathbf b)$; setting it to zero gives $A^TA\mathbf x = A^T\mathbf b$.",
        [r"Chain rule on $\|\mathbf r\|^2$ with $\mathbf r = A\mathbf x - \mathbf b$: $\nabla = 2J^T\mathbf r = 2A^T\mathbf r$.", r"Zero gradient: the normal equations."]),
    FRQ(83, 11, "11.3", r"For $A = \begin{pmatrix}1&2\\3&4\end{pmatrix}$ and $B = \begin{pmatrix}0&1\\1&0\end{pmatrix}$, compute $\operatorname{tr}(AB)$ and $\operatorname{tr}(BA)$.", "5 and 5",
        [r"$\operatorname{tr}\begin{pmatrix}2&1\\4&3\end{pmatrix} = \operatorname{tr}\begin{pmatrix}3&4\\1&2\end{pmatrix} = 5$: the trace is cyclic."]),
    FRQ(85, 11, "11.4", r"Compute $e^{At}$ for $A = \begin{pmatrix}0&1\\0&0\end{pmatrix}$.", r"$\begin{pmatrix}1&t\\0&1\end{pmatrix}$",
        [r"$A^2 = 0$, so the series stops: $e^{At} = I + At$."]),
    FRQ(89, 12, "12.1", r"In homogeneous coordinates, find the $3\times3$ matrix for &ldquo;translate by $(3, -1)$, then rotate $90^\circ$ counter-clockwise&rdquo;. Where does $(1, 0)$ go?",
        r"$\begin{pmatrix}0&-1&1\\1&0&3\\0&0&1\end{pmatrix}$; $(1, 0) \mapsto (1, 4)$.",
        [r"$RT$: the translation is applied first, so it sits on the right.", r"$(1, 0) \to (4, -1) \to (1, 4)$."]),
    FRQ(92, 12, "12.2", r"Pages $1 \to \{2, 3\}$, $2 \to \{3\}$, $3 \to \{1\}$ (no damping). Build the column-stochastic $M$ and find the PageRank vector.",
        r"$(0.4, 0.2, 0.4)$",
        [r"$M = \begin{pmatrix}0&0&1\\ \tfrac12&0&0\\ \tfrac12&1&0\end{pmatrix}$.", r"$M\mathbf r = \mathbf r$ gives $\mathbf r \propto (2, 1, 2)$; normalize."]),
    FRQ(94, 12, "12.3", r"For the path graph $1 - 2 - 3$, write $L = D - A$, its eigenvalues, and the Fiedler vector. Which split does the vector suggest?",
        r"Eigenvalues $0, 1, 3$; Fiedler vector $(1, 0, -1)$; split $\{1\}\,|\,\{3\}$ (node 2 on the boundary).",
        [r"$L = \begin{pmatrix}1&-1&0\\-1&2&-1\\0&-1&1\end{pmatrix}$.", r"The Fiedler vector&rsquo;s signs separate the endpoints; node 2 sits at 0."]),
    FRQ(96, 12, "12.4", r"Fit $y = wx$ (no intercept) by least squares to $(1, 2), (2, 3), (3, 7)$.", r"$w = 29/14$",
        [r"$w = \dfrac{\sum xy}{\sum x^2} = \dfrac{2 + 6 + 21}{1 + 4 + 9} = \dfrac{29}{14}$."]),
    FRQ(98, 12, "12.4", r"Repeat Problem 96 with ridge penalty $\lambda = 1$.", r"$w = 29/15$",
        [r"$w = \dfrac{\sum xy}{\sum x^2 + \lambda} = \dfrac{29}{15}$: shrinkage toward 0."]),
    FRQ(99, 12, "12.5", r"Centered data has covariance $C = \begin{pmatrix}3&1\\1&3\end{pmatrix}$. Find PC1, its variance, and the fraction of variance it explains.",
        r"PC1 $= \tfrac1{\sqrt2}(1, 1)$; variance 4; fraction $2/3$.",
        [r"Eigenvalues 4 (for $(1, 1)$) and 2 (for $(1, -1)$).", r"Fraction $4/(4 + 2) = 2/3$."]),
    FRQ(101, 12, "12.5", r"Using Problem 99, find the PC1 score of the centered point $\mathbf x = (2, 0)$.", r"$\sqrt2$",
        [r"Score $= \mathbf x\cdot\text{PC1} = (2, 0)\cdot\tfrac1{\sqrt2}(1, 1) = \sqrt2$."]),
    FRQ(102, 12, "12.6", r"A batch $X \in \mathbb R^{64\times784}$ goes through a dense layer with 256 outputs. Give the shape of $H$ and the number of parameters (weights plus biases).",
        r"$64\times256$; 200,960 parameters.", [r"$H = XW + \mathbf b$ with $W$ of size $784\times256$.", r"$784\cdot256 + 256 = 200{,}960$."]),
    FRQ(106, 12, "12.7", r"Take $\mathbf q = (1, 0)$, keys $\mathbf k_1 = (1, 0)$, $\mathbf k_2 = (0, 1)$, values $\mathbf v_1 = (2, 0)$, $\mathbf v_2 = (0, 2)$, and $d_k = 2$. Compute the attention weights and the output.",
        r"Weights $(0.670, 0.330)$; output $(1.340, 0.660)$.",
        [r"Scores $\mathbf q\cdot\mathbf k_i/\sqrt{d_k} = (1/\sqrt2, 0)$.", r"Softmax: $(0.670, 0.330)$.", r"Output $0.670\mathbf v_1 + 0.330\mathbf v_2$."]),
    FRQ(107, 12, "12.8", r"Find the cosine similarity of the embeddings $(1, 2, 2)$ and $(2, 1, 2)$.", r"$8/9 \approx 0.889$",
        [r"$\dfrac{2 + 2 + 4}{3\cdot3} = \dfrac89$."]),
    FRQ(108, 12, "12.9", r"For 1000 users, 500 items and rank $k = 10$, how many parameters does $R \approx UV^T$ have, compared with the full matrix?",
        r"15,000 versus 500,000.", [r"$k(m + n) = 10\cdot1500 = 15{,}000$, which is 3% of $1000\cdot500$."]),
    FRQ(109, 12, "12.9", r"LoRA with $d = 4096$ and $r = 8$: how many trainable parameters, and what fraction of the $d\times d$ matrix is that?",
        r"65,536; about 0.39%.", [r"$2dr = 2\cdot4096\cdot8 = 65{,}536$.", r"$65{,}536/4096^2 = 1/256 \approx 0.39\%$."]),
    FRQ(110, 12, "12.9", r"A $512\times512$ image is stored as a rank-50 truncated SVD. How many numbers is that, and what fraction of the original?",
        r"51,250; about 19.6%.", [r"$k(m + n + 1) = 50\cdot1025 = 51{,}250$.", r"$51{,}250/262{,}144 \approx 19.6\%$."]),
    FRQ(112, 12, "12.10", r"Same $H = \operatorname{diag}(1, 100)$ with $\eta = 0.01$: find the spectral radius of $I - \eta H$ and $\kappa(H)$. Which coordinate converges slowly?",
        r"$\rho = 0.99$; $\kappa = 100$; $x_1$ is slow.", [r"$I - \eta H = \operatorname{diag}(0.99, 0)$.", r"The $\lambda = 1$ direction shrinks only 1% per step."]),
    FRQ(113, 12, "12.11", r"For the points $(1, 0), (1, 1), (0, 1)$, form the linear-kernel Gram matrix $K = XX^T$ and find $\operatorname{rank}K$ and $\det K$.",
        r"$K = \begin{pmatrix}1&1&0\\1&2&1\\0&1&1\end{pmatrix}$; rank 2; $\det 0$.",
        [r"$K_{ij} = \mathbf x_i\cdot\mathbf x_j$.", r"Three points in $\mathbb R^2$ give rank at most 2, so $\det K = 0$."]),
